import{_ as d,o as e,c as o,a6 as a}from"./chunks/framework.BrkgobfX.js";const b=JSON.parse('{"title":"账户、诊断与其它命令","description":"登录账户、用量统计、诊断修复、语音与移动端等零散但常用的命令","frontmatter":{"title":"账户、诊断与其它命令","description":"登录账户、用量统计、诊断修复、语音与移动端等零散但常用的命令","source":"https://daiw.org/manual/claude-code/commands-misc"},"headers":[],"relativePath":"manual/agent/claude-code/commands-misc.md","filePath":"manual/agent/claude-code/commands-misc.md"}'),c={name:"manual/agent/claude-code/commands-misc.md"};function r(l,t,i,h,s,n){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="账户、诊断与其它命令" tabindex="-1">账户、诊断与其它命令 <a class="header-anchor" href="#账户、诊断与其它命令" aria-label="Permalink to &quot;账户、诊断与其它命令&quot;">​</a></h1><blockquote><p>登录账户、用量统计、诊断修复、语音与移动端等零散但常用的命令</p></blockquote><h2 id="账户与登录" tabindex="-1">账户与登录 <a class="header-anchor" href="#账户与登录" aria-label="Permalink to &quot;账户与登录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/login</code></td><td>登录 Anthropic 账号。⚠️ v2.1.273 起用 Claude 账号登录时也会请求访问你 claude.ai 上的插件</td></tr><tr><td><code>/logout</code></td><td>登出。v2.1.275 起经 Claude apps 网关登录的，若网关声明支持 token 撤销，<code>/logout</code> 也会结束网关上的会话</td></tr><tr><td><code>/status</code></td><td>打开设置界面的 Status 标签页，显示版本、模型、账号、连接状态（Claude 响应过程中也能打开）。v2.1.221 起还会显示会话类型：<code>interactive</code>，或后台作业的 <code>attached</code> / <code>unattended</code>；v2.1.261 起多一行「Organization policy」，说明组织策略为何没能加载；v2.1.274 起 GitHub 一行改叫「Cloud sessions」；v2.1.275 起经 Claude apps 网关登录时显示登录的账号；🆕 v2.1.278 起多一行「Auto mode server」，显示本会话的 auto mode 分类器是否跑在服务端；v2.1.282 起还会列出项目设置里被忽略、或把遥测关掉的遥测变量（<code>claude doctor</code> 同样列出）</td></tr><tr><td><code>/upgrade</code></td><td>打开升级页面切换到更高的订阅套餐</td></tr><tr><td><code>/privacy-settings</code></td><td>查看/修改隐私设置（仅 Pro/Max 订阅用户可见）</td></tr><tr><td><code>/passes</code></td><td>分享一周免费试用给朋友（仅符合条件的账号可见）</td></tr></tbody></table><h2 id="用量与费用" tabindex="-1">用量与费用 <a class="header-anchor" href="#用量与费用" aria-label="Permalink to &quot;用量与费用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/usage</code></td><td>查看会话花费、套餐用量上限、活跃度统计；Pro/Max/Team/Enterprise 套餐下还能按技能、subagent、插件、MCP 服务器细分。别名 <code>/cost</code>、<code>/stats</code>。v2.1.243 起新增 Loops 细分（每个 <code>/loop</code> 的运行次数与 token）；v2.1.251 / v2.1.260 起还显示本会话 prompt 缓存命中率与未命中的可能原因；🆕 v2.1.299 起新增针对 <code>max</code> 推理强度、工作流、常驻上下文与大工具结果的告警，v2.1.305 起每条告警给出单行修复说明并可按 <code>f</code> 一键应用（<code>/doctor</code> 同样提供）</td></tr><tr><td><code>/usage-credits</code></td><td>配置用量额度，在触达套餐上限后仍可继续工作（原 <code>/extra-usage</code>）</td></tr></tbody></table><h2 id="诊断与反馈" tabindex="-1">诊断与反馈 <a class="header-anchor" href="#诊断与反馈" aria-label="Permalink to &quot;诊断与反馈&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/doctor</code></td><td>技能。做一次安装与配置体检：重复或残留的安装、<code>PATH</code> 问题、无法解析的 settings 文件、没用上的技能 / MCP / 插件、慢 hook 等，先报告、经你确认再动手修复（v2.1.205 起如此，更早版本是只读的诊断界面，按 <code>f</code> 交给 Claude 修复）。别名 <code>/checkup</code>；终端里的 <code>claude doctor</code> 只打印只读的安装诊断。🆕 v2.1.283 起 <code>/doctor prompt-audit</code>（或 <code>/checkup prompt-audit</code>）审查你的 CLAUDE.md、技能、agent 与命令里为旧模型写的提示词套路，过时的路径、命令与相互矛盾的说明文件排在报告最前</td></tr><tr><td><code>/skill-doctor</code></td><td>🆕 <strong>v2.1.261+</strong>：列出哪些已加载的技能从未用上、各自占多少上下文，方便清理</td></tr><tr><td><code>/debug [description]</code></td><td>技能。为当前会话开启调试日志并分析问题；调试日志默认关闭（除非以 <code>claude --debug</code> 启动），中途运行 <code>/debug</code> 只会从此刻开始记录</td></tr><tr><td><code>/feedback [report]</code></td><td>提交反馈、报 bug 或分享会话。别名 <code>/bug</code>、<code>/share</code>。v2.1.247 起 Claude 可以在会话出问题时用 <code>SendFeedback</code> 工具起草报告，由你在这里审阅后再发送（<code>feedbackDrafts</code> 设置可关）。⚠️ v2.1.273 起报告只附上最近一次 API 请求里与模型行为有关的参数（模型、系统提示词、工具），不含请求元数据与 <code>CLAUDE_CODE_EXTRA_BODY</code> 字段</td></tr><tr><td><code>/insights</code></td><td>生成一份分析报告：你的会话都花在哪些项目区域、交互模式与卡点。🆕 v2.1.281 起报告里多了一条 auto mode 建议，估算最近的会话里有多少权限提示本可以由 auto mode 处理</td></tr><tr><td><code>/team-onboarding</code></td><td>基于过去 30 天的会话、命令、MCP 使用情况，生成一份团队 onboarding 指南</td></tr><tr><td><code>/release-notes</code></td><td>在交互式版本选择器里查看 changelog，可选查看某个具体版本或全部版本</td></tr><tr><td><code>/heapdump</code></td><td>生成 JS 堆快照与内存分析，写到桌面（或 Linux 无桌面环境时的主目录），用于排查高内存占用</td></tr></tbody></table><h2 id="mcp-集成" tabindex="-1">MCP 集成 <a class="header-anchor" href="#mcp-集成" aria-label="Permalink to &quot;MCP 集成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/mcp reconnect all</code></td><td>🆕 <strong>v2.1.284+</strong>：重试所有连接失败或需要重新认证的 MCP 服务器</td></tr></tbody></table><h2 id="ide-与浏览器集成" tabindex="-1">IDE 与浏览器集成 <a class="header-anchor" href="#ide-与浏览器集成" aria-label="Permalink to &quot;IDE 与浏览器集成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/ide</code></td><td>管理 IDE 集成并查看连接状态（⚠️ v2.1.318 起在 IDE 内置终端里启动 Claude Code 时不再自动安装或更新 IDE 扩展，请从外部终端运行 <code>/ide</code> 或在编辑器扩展面板里管理）</td></tr><tr><td><code>/chrome</code></td><td>配置 Claude in Chrome 浏览器自动化设置</td></tr><tr><td><code>/terminal-setup</code></td><td>配置 Shift+Enter 等终端快捷键（仅在需要的终端，如 VS Code、Cursor、Alacritty、Zed 中出现）</td></tr></tbody></table><h2 id="语音与移动端" tabindex="-1">语音与移动端 <a class="header-anchor" href="#语音与移动端" aria-label="Permalink to &quot;语音与移动端&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/voice [hold|tap|off]</code></td><td>开关语音听写，或指定特定模式（需要 claude.ai 账号）</td></tr><tr><td><code>/mobile</code></td><td>显示下载 Claude 移动端 App 的二维码。别名 <code>/ios</code>、<code>/android</code>。v2.1.271 起只显示一个指向 claude.ai/mobile 的二维码，由它为你的手机打开对应的应用商店</td></tr><tr><td><code>/install-slack-app</code></td><td>安装 Claude Slack App，走浏览器完成 OAuth</td></tr></tbody></table><h2 id="第三方-api-提供方配置" tabindex="-1">第三方 API 提供方配置 <a class="header-anchor" href="#第三方-api-提供方配置" aria-label="Permalink to &quot;第三方 API 提供方配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/setup-bedrock</code></td><td>交互式向导配置 Amazon Bedrock 的鉴权、区域、模型钉版（需先设置 <code>CLAUDE_CODE_USE_BEDROCK=1</code>)</td></tr><tr><td><code>/setup-vertex</code></td><td>交互式向导配置 Google Cloud&#39;s Agent Platform 的鉴权、项目、区域、模型钉版（需先设置 <code>CLAUDE_CODE_USE_VERTEX=1</code>)</td></tr></tbody></table><h2 id="杂项" tabindex="-1">杂项 <a class="header-anchor" href="#杂项" aria-label="Permalink to &quot;杂项&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/help</code></td><td>显示帮助与可用命令列表</td></tr><tr><td><code>/scroll-speed</code></td><td>交互式调整鼠标滚轮速度（仅全屏渲染模式）</td></tr><tr><td><code>/radio</code></td><td>在浏览器打开 Claude FM lo-fi 电台</td></tr><tr><td><code>/stickers</code></td><td>订购 Claude Code 周边贴纸</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>并非所有命令对所有用户都可见，取决于平台、套餐与运行环境——例如 <code>/desktop</code> 只在 macOS/Windows 且已登录订阅账号时出现，<code>/upgrade</code> 只在 Pro/Max 套餐下出现。命令列表以你本机 <code>/help</code> 或 <code>/</code> 菜单的实际展示为准。</p></div>',19)])])}const p=d(c,[["render",r]]);export{b as __pageData,p as default};
